def transform(grid):
    out=[row[:] for row in grid]
    for r,row in enumerate(grid):
        # In each nonblank signal row, recolor the zero-valued suffix after its last marked cell.
        nz=[j for j,v in enumerate(row) if v != 0]
        if nz:
            j=nz[-1]
            for c in range(j+1,len(row)):
                if row[c]==0:
                    out[r][c]=1
    return out
